import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"business-service ↔ ai-service — Internal REST Contract","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/business-ai-rest-contract.md","filePath":"architecture/business-ai-rest-contract.md"}'),n={name:"architecture/business-ai-rest-contract.md"};function d(i,e,c,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="business-service-↔-ai-service-—-internal-rest-contract" tabindex="-1"><code>business-service</code> ↔ <code>ai-service</code> — Internal REST Contract <a class="header-anchor" href="#business-service-↔-ai-service-—-internal-rest-contract" aria-label="Permalink to &quot;\`business-service\` ↔ \`ai-service\` — Internal REST Contract&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Architecture Index</a> · <a href="./service-boundaries.html">Service Boundaries</a> · <a href="./../api/openapi-spec-ai-service.html">AI OpenAPI Spec</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html">RabbitMQ Publisher Contract</a></p><p>Defines the service-to-service HTTP/REST contract, authentication headers, timeout/retry rules, durable job state machines, and atomic AI credit accounting between <code>brandhub-business-service</code> (<code>:8081</code>) and <code>brandhub-ai-service</code> (<code>:8082</code>).</p><hr><h2 id="_1-transport-network-isolation-authentication" tabindex="-1">1. Transport, Network Isolation &amp; Authentication <a class="header-anchor" href="#_1-transport-network-isolation-authentication" aria-label="Permalink to &quot;1. Transport, Network Isolation &amp; Authentication&quot;">​</a></h2><ul><li><strong>Internal Base URL</strong>: <ul><li>Local Docker (<code>brandhub-network</code>): <code>http://ai-service:8082</code></li><li>AWS Production (<code>ap-southeast-1</code>): <code>http://172.31.20.60:8082</code> (<code>brandhub-ai</code> EC2, restricted by <code>brandhub-ai-sg</code> to <code>core</code>, <code>gateway</code>, and <code>crawl</code> security groups — <strong>zero</strong> public routes on <code>brandhub-api-gateway</code>).</li></ul></li><li><strong>Authentication (<code>verify_internal_key</code>)</strong>: Every internal call carries <code>X-Internal-Key: &lt;INTERNAL_SERVICE_KEY&gt;</code> verified via constant-time comparison in <code>app/core/security.py</code>, plus <code>X-Request-Id: &lt;uuid&gt;</code> propagated from <code>RequestIdWebFilter</code> for cross-service log correlation.</li><li><strong>Timeout &amp; Retry Budget in <code>business-service</code></strong>: <ul><li><strong>Caption / Hashtag / Moderation / Collaborator / RAG Query</strong>: <code>30s</code> read timeout; at most <code>1</code> retry (<code>2s</code> backoff) on TCP connect failure; <strong>never</strong> retry <code>4xx</code> or post-inference <code>5xx</code> without idempotency keys.</li><li><strong>Synchronous Ambassador / Commercial Image (<code>Qwen Image 2.1</code>)</strong>: <code>120s</code>–<code>180s</code> read timeout (Vast.ai GPU execution).</li><li><strong>Product Video (<code>Wan 2.2 Fun VACE 14B</code>) &amp; Server Auto-Edit</strong>: Asynchronous submit + polling lifecycle (<code>202 Accepted</code> / <code>jobId</code> polling) coordinated via PostgreSQL <code>product_video_*</code> and MongoDB <code>video_auto_edits</code> leases.</li></ul></li></ul><hr><h2 id="_2-complete-service-to-service-endpoint-mapping" tabindex="-1">2. Complete Service-to-Service Endpoint Mapping <a class="header-anchor" href="#_2-complete-service-to-service-endpoint-mapping" aria-label="Permalink to &quot;2. Complete Service-to-Service Endpoint Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Business Caller / Domain</th><th style="text-align:left;"><code>ai-service</code> Method &amp; Path</th><th style="text-align:center;">SRS FR / Feature</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Caption &amp; Copywriting</strong> (<code>AiCaptionService</code>, <code>AiGenerationController</code>)</td><td style="text-align:left;"><code>POST /api/v1/ai/content/generate</code>&lt;br&gt;<code>POST /api/v1/ai/content/captions/generate</code> <em>(alias)</em>&lt;br&gt;<code>POST /api/v1/ai/content/captions/refine</code>&lt;br&gt;<code>POST /api/v1/ai/content/captions/adapt</code>&lt;br&gt;<code>POST /api/v1/ai/content/hashtags</code>&lt;br&gt;<code>POST /api/v1/ai/content/moderate</code>&lt;br&gt;<code>POST /api/v1/ai/content/brand-profile/extract</code></td><td style="text-align:center;"><code>FR 3.7.6</code>, <code>3.7.14</code>, <code>3.6.33</code></td><td style="text-align:left;">Quick single-post generation, 3-variant Hybrid GraphRAG captions (<code>HOOK_DRIVEN</code>, <code>STORYTELLING</code>, <code>DIRECT_CTA</code>), platform adaptation, contextual hashtags, and safety moderation</td></tr><tr><td style="text-align:left;"><strong>Brand Knowledge RAG</strong></td><td style="text-align:left;"><code>POST /api/v1/ai/rag/documents</code>&lt;br&gt;<code>DELETE /api/v1/ai/rag/documents/{document_id}</code></td><td style="text-align:center;"><code>FR 3.7.3</code>–<code>3.7.5</code></td><td style="text-align:left;">Uploads PDF/DOCX/TXT/URL to S3, chunks (<code>500</code>/<code>50</code>), embeds (<code>384d</code>), and purges vectors from ChromaDB</td></tr><tr><td style="text-align:left;"><strong>Virtual Brand Ambassador</strong> (<code>AiGenerationController</code>)</td><td style="text-align:left;"><code>GET /api/v1/ai/ambassadors/presets</code>&lt;br&gt;<code>POST /api/v1/ai/ambassadors/generate</code>&lt;br&gt;<code>POST /api/v1/ai/ambassadors/character-sheet</code></td><td style="text-align:center;"><code>FR 3.7.7</code></td><td style="text-align:left;">Lists built-in model presets; generates custom portrait &amp; 3-angle character turnaround sheet via Vast.ai Qwen 2.1</td></tr><tr><td style="text-align:left;"><strong>Commercial Ad Image</strong> (<code>AiGenerationController</code>)</td><td style="text-align:left;"><code>POST /api/v2/ai/image/commercial/generate</code>&lt;br&gt;<code>GET /api/v2/ai/image/commercial/generations/{id}</code>&lt;br&gt;<code>GET /api/v2/ai/image/commercial/health</code></td><td style="text-align:center;"><code>FR 3.7.8</code>–<code>3.7.9</code></td><td style="text-align:left;">3-reference Qwen Image 2.1 composition (Ambassador + Product + Style/Pose) across <code>4:5</code>, <code>9:16</code>, <code>16:9</code>, or <code>auto</code></td></tr><tr><td style="text-align:left;"><strong>Short &amp; Product Video</strong> (<code>AiVideoController</code>, <code>ProductVideoController</code>)</td><td style="text-align:left;"><code>GET /api/v1/ai/video/styles</code>&lt;br&gt;<code>POST /api/v1/ai/video/generate</code>&lt;br&gt;<code>GET /api/v1/ai/video/{job_id}/status</code>&lt;br&gt;<code>POST /api/v1/ai/product-video/plan</code>&lt;br&gt;<code>POST /api/v1/ai/product-video/render</code>&lt;br&gt;<code>GET /api/v1/ai/product-video/render/{render_id}</code></td><td style="text-align:center;"><code>FR 3.7.10</code>–<code>3.7.11</code></td><td style="text-align:left;">Claude director + Vast.ai <strong>Wan 2.2 Fun VACE 14B</strong> 15–20s video generation and multi-scene durable product video rendering</td></tr><tr><td style="text-align:left;"><strong>Server Video Auto-Edit</strong> (<code>VideoAutoEditController</code>)</td><td style="text-align:left;"><code>POST /api/v1/ai/video-edit/plan</code>&lt;br&gt;<code>GET /api/v1/ai/video-edit/plans/{job_id}</code>&lt;br&gt;<code>POST /api/v1/ai/video-edit/jobs</code>&lt;br&gt;<code>GET /api/v1/ai/video-edit/jobs/{job_id}</code>&lt;br&gt;<code>GET|PUT /api/v1/ai/video-edit/memory/{ws}/{owner}</code>&lt;br&gt;<code>GET /api/v1/ai/video-edit/capabilities</code></td><td style="text-align:center;">Video Space</td><td style="text-align:left;">Agentic timeline planning, automated video assembly, and per-user editing preference memory</td></tr><tr><td style="text-align:left;"><strong>Trends, Graph &amp; Crawler Admin</strong> (<code>WorkspaceTrendController</code>, <code>AdminTrend*Controller</code>)</td><td style="text-align:left;"><code>GET /api/v1/ai/trends</code> · <code>POST /api/v1/ai/trends/for-brand</code>&lt;br&gt;<code>GET /api/v1/ai/trends/boards/{source}</code> · <code>/summary</code>&lt;br&gt;<code>GET /api/v1/ai/trends/explore/{,matrix,history}</code>&lt;br&gt;<code>GET|POST /api/v1/ai/trends/{crawl-config,crawl-runs,crawl-cookie,pipeline-config}</code>&lt;br&gt;<code>ANY /api/v1/ai/trends/pipeline/**</code>&lt;br&gt;<code>GET|POST /api/v1/ai/trends/replays/**</code>&lt;br&gt;<code>GET|POST /api/v1/ai/graph/explorer/**</code> · <code>/ai/graph/**</code></td><td style="text-align:center;"><code>FR 3.7.1</code>–<code>3.7.2</code>, <code>3.7.13</code></td><td style="text-align:left;">Workspace trend discovery, brand-fit ranking, Neo4j Knowledge Graph explorer, replay evaluation, and <code>Admin</code> crawler control</td></tr><tr><td style="text-align:left;"><strong>Collaborators &amp; Moodboard References</strong></td><td style="text-align:left;"><code>POST /api/v1/ai/collaborators/recommend</code>&lt;br&gt;<code>POST /api/v1/ai/references/{recommend,unfurl}</code></td><td style="text-align:center;"><code>FR 3.7.19</code></td><td style="text-align:left;">Ranks third-party KOL/Press/Banner/TV collaborators (<code>third_party_collaborators</code>) and recommends moodboard references</td></tr><tr><td style="text-align:left;"><strong>System Health &amp; Backups</strong></td><td style="text-align:left;"><code>GET /health</code>&lt;br&gt;<code>GET /internal/ai/trends/{fetch,dependencies}</code>&lt;br&gt;<code>GET|POST /internal/ai/backups/{health,status,run,restore}</code></td><td style="text-align:center;"><code>FR 3.10.3</code></td><td style="text-align:left;">Liveness and internal dependency probes</td></tr></tbody></table><hr><h2 id="_3-atomic-double-entry-ai-credit-settlement-protocol" tabindex="-1">3. Atomic Double-Entry AI Credit Settlement Protocol <a class="header-anchor" href="#_3-atomic-double-entry-ai-credit-settlement-protocol" aria-label="Permalink to &quot;3. Atomic Double-Entry AI Credit Settlement Protocol&quot;">​</a></h2><p><code>brandhub-business-service</code> (<code>AiCreditGenerationService</code> + <code>ProductVideoStore</code>) guarantees zero unbilled GPU/LLM execution and zero lost credits on upstream failure:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Price &amp; Quota Check (PostgreSQL ACID):</span></span>
<span class="line"><span>   - Resolve unit cost from ai_credit_operation_prices (managed by Admin via FR 3.10.10–3.10.12).</span></span>
<span class="line"><span>   - Verify workspace monthly cap in workspace_credit_limits (set by Owner via FR 3.9.6).</span></span>
<span class="line"><span>   - Lock available grant balances in agency_credit_wallets / credit_grants (FIFO by expires_at).</span></span>
<span class="line"><span>   - Insert ai_credit_reservations + credit_reservation_allocations (bound to idempotency_key).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Dispatch to ai-service (:8082, X-Internal-Key):</span></span>
<span class="line"><span>   - Synchronous (Caption / Ambassador / Commercial Image) OR Asynchronous (Video / Product Video).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3a. On COMPLETED:</span></span>
<span class="line"><span>    - Record CAPTURE in credit_operations &amp; credit_entries; persist output metadata in ai_caption_generations /</span></span>
<span class="line"><span>      ai_video_jobs / product_video_productions. Replaying the same idempotency_key returns the cached output.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3b. On FAILED / Timeout / Invalid Director Script:</span></span>
<span class="line"><span>    - Record RELEASE in credit_operations &amp; credit_entries, restoring 100% of reserved credits back to</span></span>
<span class="line"><span>      credit_grants.available and decrementing workspace_credit_usage (BR-48, BR-60).</span></span></code></pre></div>`,13)])])}const b=t(n,[["render",d]]);export{u as __pageData,b as default};
